import { test, expect } from '@playwright/test';

test.describe('JavaScript Alerts Modal Dialogs', () => {
  test('should confirm the alert dialog and show the result', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    await page.click('a#confirm');
    await expect(page).toHaveURL(/.*javascript_alerts/);
    await expect(page.locator('#result')).toBeVisible();
    await expect(page.locator('#result')).toHaveText('You clicked: Ok');
  });

  test('should not change URL when clicking the button again', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    await page.click('a#confirm');
    await expect(page).toHaveURL(/.*javascript_alerts/);
    await expect(page.locator('#result')).toBeVisible();
    await expect(page.locator('#result')).toHaveText('You clicked: Ok');
    await page.click('a#confirm');
    await expect(page).toHaveURL(/.*javascript_alerts/);
    await expect(page.locator('#result')).toBeVisible();
    await expect(page.locator('#result')).toHaveText('You clicked: Ok');
  });
});
